{
  "items": [
    {
      "name": "Finsupp.sum",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "definition",
      "type": "{α : Type u_1} → {M : Type u_8} → {N : Type u_10} → [inst : Zero M] → [AddCommMonoid N] → (α →₀ M) → (α → M → N) → N"
    },
    {
      "name": "Finsupp.sum_fintype",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] [inst_2 : Fintype α]\n  (f : α →₀ M) (g : α → M → N), (∀ (i : α), g i 0 = 0) → f.sum g = ∑ i, g i (f i)"
    },
    {
      "name": "Finsupp.sum_of_support_subset",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : AddCommMonoid N] (f : α →₀ M) {s : Finset α},\n  f.support ⊆ s → ∀ (g : α → M → N), (∀ i ∈ s, g i 0 = 0) → f.sum g = ∑ x ∈ s, g x (f x)"
    },
    {
      "name": "Finset.le_sum_of_subadditive",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} {N : Type u_5} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N]\n  [inst_2 : PartialOrder N] [IsOrderedAddMonoid N] (f : M → N),\n  f 0 ≤ 0 → (∀ (x y : M), f (x + y) ≤ f x + f y) → ∀ (s : Finset ι) (g : ι → M), f (∑ i ∈ s, g i) ≤ ∑ i ∈ s, f (g i)"
    },
    {
      "name": "Multiset.le_sum_of_subadditive_on_pred",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Multiset",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {β : Type u_3} [inst : AddCommMonoid α] [inst_1 : AddCommMonoid β] [inst_2 : PartialOrder β]\n  [IsOrderedAddMonoid β] (f : α → β) (p : α → Prop),\n  f 0 ≤ 0 →\n    p 0 →\n      (∀ (a b : α), p a → p b → f (a + b) ≤ f a + f b) →\n        (∀ (a b : α), p a → p b → p (a + b)) →\n          ∀ (s : Multiset α), (∀ (a : α), a ∈ s → p a) → f s.sum ≤ (Multiset.map f s).sum"
    }
  ]
}
